CREATE OR REPLACE FUNCTION public.c3_current_snapshot_asset_evidence()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_content_hash text;
  v_hash_algorithm text;
  v_asset_standing text;
  v_custody_type text;
  v_custody_provider text;
  v_custody_identifier text;
  v_custody_location text;
  v_tokenization_standing text;
  v_external_anchor jsonb;
begin
  if new.asset_key is null or length(btrim(new.asset_key)) = 0 then
    return new;
  end if;

  if to_regclass('public.c3ops_asset_record') is null then
    raise exception 'HOLD_C3OPS_ASSET_AUTHORITY_UNAVAILABLE';
  end if;

  execute $asset$
    select
      content_hash,
      hash_algorithm,
      standing,
      authoritative_custody_type,
      authoritative_custody_provider,
      authoritative_custody_identifier,
      authoritative_custody_location,
      tokenization_standing,
      nullif(
        jsonb_strip_nulls(
          jsonb_build_object(
            'external_anchor_type', external_anchor_type,
            'network_identifier', network_identifier,
            'smart_contract_identifier', contract_identifier,
            'token_identifier', token_identifier,
            'anchor_standing', anchor_standing
          )
        ),
        '{}'::jsonb
      )
    from public.c3ops_asset_record
    where asset_key = $1
  $asset$
  into
    v_content_hash,
    v_hash_algorithm,
    v_asset_standing,
    v_custody_type,
    v_custody_provider,
    v_custody_identifier,
    v_custody_location,
    v_tokenization_standing,
    v_external_anchor
  using btrim(new.asset_key);

  if v_content_hash is null then
    raise exception 'HOLD_ASSET_EVIDENCE_UNRESOLVED: %', new.asset_key;
  end if;

  new.content_hash := v_content_hash;
  new.hash_algorithm := coalesce(nullif(v_hash_algorithm, ''), 'sha256');
  new.authoritative_custody_type := v_custody_type;
  new.authoritative_custody_provider := v_custody_provider;
  new.authoritative_custody_identifier := v_custody_identifier;
  new.authoritative_custody_location := v_custody_location;
  new.evidence_standing := v_asset_standing;
  new.tokenization_standing_at_attest := v_tokenization_standing;
  new.external_anchor_ref_at_attest := v_external_anchor;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.c3_current_require_successor()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if old.is_current is true and new.is_current is false then
    if not exists (
      select 1
      from public.c3_current_state successor
      where successor.predecessor_current_state_key = old.current_state_key
        and successor.env_key = old.env_key
        and successor.is_current is true
    ) then
      raise exception 'superseded Current state % requires a current successor', old.current_state_key;
    end if;
  end if;

  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.c3_current_validate_lineage()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  predecessor public.c3_current_state%rowtype;
begin
  if new.predecessor_current_state_key is null then
    if new.state_version <> 1 then
      raise exception 'initial Current state must use state_version 1';
    end if;

    if exists (
      select 1 from public.c3_current_state s where s.env_key = new.env_key
    ) then
      raise exception 'Current history already exists for env_key %', new.env_key;
    end if;

    return new;
  end if;

  select *
    into predecessor
  from public.c3_current_state
  where current_state_key = new.predecessor_current_state_key;

  if not found then
    raise exception 'predecessor Current state not found: %', new.predecessor_current_state_key;
  end if;

  if predecessor.env_key <> new.env_key then
    raise exception 'Current predecessor env_key mismatch';
  end if;

  if new.state_version <> predecessor.state_version + 1 then
    raise exception 'Current successor state_version must equal predecessor + 1';
  end if;

  if predecessor.is_current is true or predecessor.superseded_at is null then
    raise exception 'Current predecessor must be superseded before successor insertion';
  end if;

  if new.advance_disposition_ref is null
     or length(btrim(new.advance_disposition_ref)) = 0 then
    raise exception 'Current successor requires governed advance_disposition_ref';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.c3_guard_profile_pac_envpac_rebind()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
  begin
    if old.pac_type = 'ProfilePAC'
       and new.envpac_key is distinct from old.envpac_key then
      raise exception 'DNR_PROFILE_CHAIN: formed ProfilePAC cannot move between EnvPACs';
    end if;
    return new;
  end;
  $function$

CREATE OR REPLACE FUNCTION public.c3_guard_registrar_pac_supersession_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_result jsonb;
begin
  if new.registration_protocol='registrar_v1'
     and new.supersedes_pac_key is not null then
    v_result:=public.c3_validate_pac_supersession_v1(to_jsonb(new),true);

    if coalesce(v_result->>'standing','HLD')<>'PASS' then
      raise exception 'HLD_PAC_SUPERSESSION:%',
        coalesce(v_result->>'reason','supersession_unresolved');
    end if;
  end if;

  return new;
end $function$

CREATE OR REPLACE FUNCTION public.c3_pac_registrar_v1_completeness_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_eval public.c3_pac_boundary_evaluation%rowtype;
  v_call public.c3_ci_role_call%rowtype;
begin
  if new.registration_protocol<>'registrar_v1' then return null; end if;

  select * into v_eval from public.c3_pac_boundary_evaluation where evaluation_key=new.boundary_evaluation_key;
  if not found or v_eval.notchazz_result<>'PASS' or v_eval.presented_registration_sha256<>new.registration_sha256 then
    raise exception 'registrar_v1_boundary_pass_exact_match_required';
  end if;

  if not exists(
    select 1 from public.c3_pac_schema
    where schema_key=new.schema_key and pac_type=new.pac_type and standing='active' and is_active=true
  ) then
    raise exception 'registrar_v1_active_schema_required';
  end if;

  if coalesce((select requires_c3_model_binding from public.c3_pac_schema where schema_key=new.schema_key),true)
     and not exists(select 1 from public.c3_pac_model_binding b where b.pac_key=new.pac_key and b.standing='active') then
    raise exception 'registrar_v1_model_binding_required';
  end if;

  if not exists(select 1 from public.c3_pac_encounter_scope s where s.pac_key=new.pac_key and s.standing='active') then
    raise exception 'registrar_v1_encounter_scope_required';
  end if;

  select * into v_call
  from public.c3_ci_role_call
  where role_call_key=new.registrar_role_call_key;

  if not found
     or v_call.call_class<>'pac_registration'
     or v_call.caller_role_key<>'c3_notchazz_boundary_v1'
     or v_call.callee_role_key<>'c3_registrar_ci_v1'
     or v_call.standing<>'RETURNED'
     or v_call.boundary_evaluation_key<>new.boundary_evaluation_key
     or v_call.presented_sha256<>new.registration_sha256 then
    raise exception 'registrar_v1_role_call_required';
  end if;

  if not exists(
    select 1 from public.c3_pac_registration_receipt r
    where r.pac_key=new.pac_key
      and r.registration_sha256=new.registration_sha256
      and r.registrar_role_call_key=new.registrar_role_call_key
      and r.standing='registered'
  ) then
    raise exception 'registrar_v1_registration_receipt_required';
  end if;

  if new.owner_subject_type='institution'
     and coalesce((public.resolve_institutional_pac_eligibility_v1(new.owner_subject_key,new.owner_environment_key)->>'standing'),'HLD')<>'PASS' then
    raise exception 'HLD_INSTITUTIONAL_SEAT_REQUIRED';
  end if;
  return null;
end $function$

CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.c3_hardened_pac_child_guard_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_parent_column text := nullif(TG_ARGV[0],'');
  v_old_pac_key text;
  v_new_pac_key text;
  v_old_protocol text;
  v_new_protocol text;
  v_context text := current_setting('c3.pac_registrar_context',true);
begin
  if v_parent_column is null then
    raise exception 'hardened PAC child guard parent key argument is required';
  end if;

  if TG_OP in ('UPDATE','DELETE') then
    v_old_pac_key := nullif(to_jsonb(OLD)->>v_parent_column,'');
    if v_old_pac_key is null then
      raise exception 'hardened PAC child guard old parent unresolved for table % column %',
        TG_TABLE_NAME, v_parent_column;
    end if;

    select registration_protocol
      into v_old_protocol
    from public.c3_pac
    where pac_key=v_old_pac_key;
  end if;

  if TG_OP in ('INSERT','UPDATE') then
    v_new_pac_key := nullif(to_jsonb(NEW)->>v_parent_column,'');
    if v_new_pac_key is null then
      raise exception 'hardened PAC child guard new parent unresolved for table % column %',
        TG_TABLE_NAME, v_parent_column;
    end if;

    select registration_protocol
      into v_new_protocol
    from public.c3_pac
    where pac_key=v_new_pac_key;
  end if;

  if nullif(v_context,'') is null
     and (v_old_protocol='registrar_v1' or v_new_protocol='registrar_v1') then
    raise exception 'registrar_v1 PAC child state is immutable; supersede through Registrar';
  end if;

  if TG_OP='DELETE' then
    return OLD;
  end if;
  return NEW;
end $function$

CREATE OR REPLACE FUNCTION public.c3_guard_profile_pac_chain()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_envpac_key text;
  v_owner_type text;
  v_owner_key text;
  v_formed_from_c1 boolean;
  v_primitive_ok boolean;
  v_registration_protocol text;
  v_schema_key text;
  v_contract_key text;
  v_environment_class text;
  v_parent_environment text;
begin
  select p.envpac_key,p.registration_protocol,p.schema_key,p.contract_key
    into v_envpac_key,v_registration_protocol,v_schema_key,v_contract_key
  from public.c3_pac p
  where p.pac_key=new.pac_key
    and p.pac_type='ProfilePAC'
    and p.is_effective=true;

  if v_envpac_key is null then
    raise exception 'DNR_PROFILE_CHAIN: effective ProfilePAC base record not resolved';
  end if;

  if v_registration_protocol='registrar_v1' then
    if not exists(
      select 1
      from public.c3_pac_schema s
      where s.schema_key=v_schema_key
        and s.pac_type='ProfilePAC'
        and s.standing='active'
        and s.is_active=true
    ) then
      raise exception 'DNR_PROFILE_CHAIN: active ProfilePAC schema not resolved';
    end if;
  elsif v_contract_key is distinct from 'pac_contract_profilepac_v1' then
    raise exception 'DNR_PROFILE_CHAIN: legacy ProfilePAC contract not resolved';
  end if;

  select e.owner_subject_type,
         e.owner_subject_key,
         coalesce((e.metadata->>'formed_from_c1')::boolean,false),
         ce.environment_class,
         ce.metadata->>'parent_environment'
    into v_owner_type,v_owner_key,v_formed_from_c1,v_environment_class,v_parent_environment
  from public.c3_envpac e
  join public.c3_environment ce on ce.env_key=e.env_key and ce.is_active=true
  where e.envpac_key=v_envpac_key
    and e.is_effective=true;

  if v_owner_key is null then
    raise exception 'DNR_PROFILE_CHAIN: effective ProfilePAC EnvPAC not resolved';
  end if;

  if v_registration_protocol='registrar_v1' then
    if v_owner_type<>'individual'
       or not v_formed_from_c1
       or v_environment_class<>'c3me_individual_environment'
       or v_parent_environment<>'env_c3_community_connect' then
      raise exception 'DNR_PROFILE_CHAIN: hardened ProfilePAC requires current personal c1My_Env lineage';
    end if;
  else
    if not v_formed_from_c1 then
      raise exception 'DNR_PROFILE_CHAIN: ProfilePAC requires effective personal c1My_Env formed from Connect';
    end if;

    select exists(
      select 1
      from public.c3_envpac_runtime_primitive rp
      where rp.envpac_key=v_envpac_key
        and rp.primitive_key='profile_pac'
        and rp.primitive_class='participant_formable_pac'
        and rp.standing='active'
        and rp.config->>'contract_key'='pac_contract_profilepac_v1'
    ) into v_primitive_ok;

    if not v_primitive_ok then
      raise exception 'DNR_PROFILE_CHAIN: active ProfilePAC primitive not resolved from c1My_Env';
    end if;
  end if;

  if new.subject_type is distinct from v_owner_type
     or new.subject_key is distinct from v_owner_key then
    raise exception 'DNR_PROFILE_CHAIN: ProfilePAC subject must equal c1My_Env owner';
  end if;

  if tg_op='UPDATE' then
    if new.subject_type is distinct from old.subject_type
       or new.subject_key is distinct from old.subject_key
       or new.profile_class is distinct from old.profile_class then
      raise exception 'DNR_PROFILE_CHAIN: ProfilePAC identity binding is immutable after formation';
    end if;
  end if;

  return new;
end $function$

